import ast, glob, sys
role, tf, lo, hi = sys.argv[1], sys.argv[2], int(sys.argv[3]), int(sys.argv[4])
STD = set(sys.stdlib_module_names)
NET = ("urllib", "http", "socket")
def tree(p):
    return ast.parse(open(p, encoding="utf-8").read(), p)
def imports(p):
    out = []
    for n in ast.walk(tree(p)):
        if isinstance(n, ast.Import):
            out += [a.name for a in n.names]
        elif isinstance(n, ast.ImportFrom) and n.level == 0:
            out.append(n.module or "")
    return [m.split(".")[0] for m in out if m]
bad = []
for p in sorted(glob.glob("ethsc/*.py")):
    for t in imports(p):
        if t in NET and p != "ethsc/rpc.py":
            bad.append("No Network In Core: %s imports %s" % (p, t))
        elif t not in STD and t != "ethsc" and not (p == "ethsc/charts.py" and t == "matplotlib"):
            bad.append("Stdlib Only: %s imports %s" % (p, t))
for p in ("ethsc/cli.py", "ethsc/cluster.py"):
    for n in ast.walk(tree(p)):
        if isinstance(n, ast.Attribute) and n.attr.startswith("_") and not n.attr.startswith("__") and not (isinstance(n.value, ast.Name) and n.value.id == "self"):
            bad.append("%s:%d touches a private attribute %s; use the public methods" % (p, n.lineno, n.attr))
if "sqlite3" in imports("ethsc/cluster.py"):
    bad.append("ethsc/cluster.py imports sqlite3; read the store through its public methods")
for f in tree("ethsc/cluster.py").body:
    if isinstance(f, ast.FunctionDef) and f.name in ("find_similar", "match_watchlist", "recheck_watchlist"):
        for n in ast.walk(f):
            if (isinstance(n, ast.Attribute) and n.attr == "code_by_id") or (isinstance(n, ast.Name) and n.id == "code_by_id"):
                bad.append("ethsc/cluster.py:%d: %s reads code_by_id (phase 11)" % (n.lineno, f.name))
            if isinstance(n, ast.Call) and isinstance(n.func, ast.Name) and n.func.id == "similarity":
                bad.append("ethsc/cluster.py:%d: %s calls similarity (phase 11)" % (n.lineno, f.name))
for p in ("tests/helpers.py", tf):
    for t in imports(p):
        if t in NET:
            bad.append("%s imports %s" % (p, t))
t = tree(tf)
tests = [n.name for n in ast.walk(t) if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef)) and n.name.startswith("test_")]
if not (lo <= len(tests) <= hi):
    bad.append("%s has %d test_* functions; want %d..%d (%s)" % (tf, len(tests), lo, hi, role))
for n in ast.walk(t):
    if isinstance(n, ast.ClassDef) and n.name.startswith("Fake"):
        bad.append("%s defines its own stub %s; import stubs from tests/helpers.py" % (tf, n.name))
    if isinstance(n, ast.Attribute) and n.attr == "maxDiff" and role != "judge":
        bad.append("%s touches maxDiff; smoke tests compare short values" % tf)
print("\n".join(bad) if bad else "guard OK")
sys.exit(1 if bad else 0)
